SELECT id, name, phone, gender, birthday, level, balance, points, source, status, dept_id, remark, create_time FROM salon_member
deleted = 0
AND ( name LIKE CONCAT('%', #{q.keywords}, '%') OR phone LIKE CONCAT('%', #{q.keywords}, '%') )
AND status = #{q.status}
AND dept_id = #{q.deptId}
ORDER BY create_time DESC
